const CHECK_ALPHABET = "ACDEFGHJKLMNPQRSTUVWXYZ";
const CODE_PATTERN = /^V([0-9]{2})-([A-Z]+)-([0-9]{3})([A-Z])$/;

function rowToLabel(row) {
	let label = "";
	let n = row;
	while (n > 0) {
		n -= 1;
		label = String.fromCharCode(65 + (n % 26)) + label;
		n = Math.floor(n / 26);
	}
	return label;
}

function labelToRow(label) {
	let row = 0;
	for (const ch of label) {
		row = row * 26 + (ch.charCodeAt(0) - 64);
	}
	return row;
}

function checkLetter(text) {
	let sum = 0;
	for (let i = 0; i < text.length; i++) {
		sum += text.charCodeAt(i);
	}
	return CHECK_ALPHABET[sum % CHECK_ALPHABET.length];
}

/** @param {{ venue: number, row: number, seat: number }} ticket @returns {string} */
export function encodeTicket(ticket) {
	const { venue, row, seat } = ticket ?? {};
	if (!Number.isInteger(venue) || venue < 1 || venue > 99) {
		throw new RangeError("venue must be an integer from 1 to 99");
	}
	if (!Number.isInteger(row) || row < 1) {
		throw new RangeError("row must be an integer of 1 or more");
	}
	if (!Number.isInteger(seat) || seat < 1 || seat > 999) {
		throw new RangeError("seat must be an integer from 1 to 999");
	}
	const body = `V${String(venue).padStart(2, "0")}-${rowToLabel(row)}-${String(seat).padStart(3, "0")}`;
	return `${body}-${checkLetter(body)}`;
}

/** @param {string} code @returns {{ venue: number, row: number, seat: number }} */
export function decodeTicket(code) {
	if (typeof code !== "string") {
		throw new SyntaxError("code must be a string");
	}
	const match = CODE_PATTERN.exec(code);
	if (!match) {
		throw new SyntaxError("code does not match the expected form");
	}
	const [, venueDigits, rowLabel, seatDigits, givenCheck] = match;
	const venue = Number(venueDigits);
	const seat = Number(seatDigits);
	const expectedCheck = checkLetter(code.slice(0, -2));
	if (venue < 1) {
		throw new RangeError("venue must be from 1 to 99");
	}
	if (seat < 1) {
		throw new RangeError("seat must be from 1 to 999");
	}
	if (givenCheck !== expectedCheck) {
		throw new RangeError("check letter is wrong");
	}
	return { venue, row: labelToRow(rowLabel), seat };
}

