node --test && node -e '
import("./src/ticket-code.js").then(({ encodeTicket, decodeTicket }) => {
  // row label mappings
  for (const [row, label] of [[1,"A"],[26,"Z"],[27,"AA"],[52,"AZ"],[53,"BA"],[702,"ZZ"],[703,"AAA"]]) {
    const code = encodeTicket({ venue: 1, row, seat: 1 });
    if (!code.includes(`-${label}-`)) throw new Error("bad label for row " + row + ": " + code);
    if (decodeTicket(code).row !== row) throw new Error("bad inverse for row " + row);
  }
  // round-trip
  for (let v = 1; v <= 99; v++) for (const s of [1, 999]) for (const r of [1, 28, 703, 10000]) {
    const c = encodeTicket({ venue: v, row: r, seat: s });
    const d = decodeTicket(c);
    if (d.venue !== v || d.row !== r || d.seat !== s) throw new Error("roundtrip fail " + c);
  }
  // encode errors
  const mustRange = (f, msg) => { try { f(); } catch (e) { if (!(e instanceof RangeError)) throw new Error("expected RangeError: " + msg); } };
  mustRange(() => encodeTicket({ venue: 0, row: 1, seat: 1 }), "venue 0");
  mustRange(() => encodeTicket({ venue: 100, row: 1, seat: 1 }), "venue 100");
  mustRange(() => encodeTicket({ venue: "7", row: 1, seat: 1 }), "venue string");
  mustRange(() => encodeTicket({ venue: 7.5, row: 1, seat: 1 }), "venue 7.5");
  mustRange(() => encodeTicket({ venue: 1, row: 0, seat: 1 }), "row 0");
  mustRange(() => encodeTicket({ venue: 1, row: 1.5, seat: 1 }), "row 1.5");
  mustRange(() => encodeTicket({ venue: 1, row: 1, seat: 0 }), "seat 0");
  mustRange(() => encodeTicket({ venue: 1, row: 1, seat: 1000 }), "seat 1000");
  mustRange(() => encodeTicket({ venue: 1, row: 1, seat: "1" }), "seat string");
  mustRange(() => encodeTicket(null), "null");
  // decode syntax errors
  const mustSyntax = (code, msg) => { try { decodeTicket(code); } catch (e) { if (!(e instanceof SyntaxError)) throw new Error("expected SyntaxError: " + msg); } };
  mustSyntax(123, "non-string");
  mustSyntax("v07-AB-012-G", "lowercase v");
  mustSyntax("V07-ab-012-G", "lowercase row");
  mustSyntax("V07-AB-12-G", "2-digit seat");
  mustSyntax("V07-AB-0123-G", "4-digit seat");
  mustSyntax("V7-AB-012-G", "1-digit venue");
  mustSyntax("V07--012-G", "empty row");
  mustSyntax("V07-7B-012-G", "non-letter row");
  mustSyntax("V07-AB-012", "missing check");
  mustSyntax("V07-AB-012-GX", "extra part");
  mustSyntax("", "empty");
  // decode range errors
  const mustDecodeRange = (code, msg) => { try { decodeTicket(code); } catch (e) { if (!(e instanceof RangeError)) throw new Error("expected RangeError: " + msg); } };
  mustDecodeRange("V00-AB-012-G", "venue 00");
  mustDecodeRange("V01-A-000-A", "seat 000");
  mustDecodeRange("V07-AB-012-A", "wrong check");
  mustDecodeRange("V07-AB-012-B", "check outside alphabet");
  console.log("all sanity checks passed");
});'
